@spec parts_spec  src=tests/specs/parts_spec.lua  loc=195  cases=13
@exercises editCursor (ec)
@surface   ec:decorateCol

# Intent
  Pinning specs for the column-parts shape: ec:decorateCol stamps
  col.parts (ordered name list), col.stopPos (absolute char offsets per
  stop), col.partAt (part name per stop), col.partStart (stop index of
  first stop in this stop's part), and col.width (sum of part widths +
  inter-part separators). Behaviour-preserving refactor — these pin the
  shape so a future addition (e.g. tracker-mode `sample` part) can't
  silently drift the layout of existing col types.

# Helpers
  @fn mkCol(type, showDelay, trackerMode, showCents)  @ 14-19
      -- decorateCol only reads col.type, col.showDelay, col.trackerMode and
      -- col.showCents. We don't need a full harness — a minimal shell is enough.
  @fn decorate(col, pitchWidth, octaveWidth)  @ 23-31
      -- Decorate a col through ec; ec needs deps but only `grid` is touched by
      -- decorateCol. Pass an empty grid.

# Cases
  @case 'note (no delay): parts={pitch,vel}; stopPos={0,2,4,5}; width=6'  [pure]  @ 36-42
  @case 'note+delay: parts={pitch,vel,delay}; stopPos={0,2,4,5,7,8,9}; width=10'  [pure]  @ 46-52
  @case 'note pitch width follows the active temper: width 4 → stopPos {0,3,5,6}, width 7'  [pure]  @ 56-62
  @case 'a two-char octave field takes a stop each: width 4 → pitch stops {0,2,3}'  [pure]  @ 68-73
  @case 'pb: parts={pb}; stopPos={0,1,2,3}; width=4'  [pure]  @ 77-83
  @case 'scalar (cc): parts={val}; stopPos={0,1}; width=2'  [pure]  @ 90-96
  @case '14-bit cc: parts={val}; stopPos={0,1,2,3}; width=4'  [pure]  @ 102-110
  @case 'partAt mirrors stops: note+delay = {pitch,pitch,vel,vel,delay,delay,delay}'  [pure]  @ 114-119
  @case 'partStart pins ordering: note+delay = {1,1,3,3,5,5,5}'  [pure]  @ 127-131
  @case 'note tracker (no delay): parts={pitch,sample,vel}; stopPos={0,2,4,5,7,8}; width=9'  [pure]  @ 141-150
  @case 'note tracker + delay: parts={pitch,sample,vel,delay}; stopPos={0,2,4,5,7,8,10,11,12}; width=13'  [pure]  @ 154-164
  @case 'note showing cents: one wider, vel shifted right, parts unchanged'  [pure]  @ 175-182
  @case 'note showing cents in tracker mode: the readout sits against the pitch'  [pure]  @ 186-193

# Uses (outbound edges)
  @use call ec:decorateCol  @ 29

